input.sparql:
SELECT ?node WHERE {
  ?node a brick:Zone ; rdfs:label ?label .
  FILTER(str(?node) LIKE "%Perimeter_mid_ZN_3%")
}

SELECT ?point ?ts WHERE {
  ?point brick:isPointOf ?zone .
  ?zone rdfs:label "Perimeter_mid_ZN_3" .
  ?point ref:hasExternalReference ?ext .
  ?ext ref:hasTimeseriesId ?ts .
}

SELECT ?u ?qk ?c WHERE {
  ?p ref:hasExternalReference ?ext .
  ?ext ref:hasTimeseriesId ?id .
  ?p qudt:hasUnit ?u .
  ?p qudt:hasQuantityKind ?qk .
}
